mapper.select:
SELECT code, status, sort FROM sys_enclosure_dictionary where type = 8 and bool_delete_enum = 0
and status = #{status}
group by code, status, sort order by sort asc

SELECT *
FROM sys_enclosure_dictionary
where name = #{name}
  AND label = #{label}
  and type = #{type}
  and bool_delete_enum = 0

SELECT ifnull(MAX(ed.sort + 1), 1) sort
FROM sys_enclosure_dictionary ed
where ed.name = #{name}
  and ed.type = #{type}
  and bool_delete_enum = 0

select *
from sys_enclosure_dictionary
where type = #{type}
  and code = #{code}
  and bool_delete_enum = 0

select label
from sys_enclosure_dictionary
where type = #{type}
  and name = #{name}
  and bool_delete_enum = 0
